def combination_sum3(k, n):
    result = []
    path = []

    def backtrack(start, remaining):
        if len(path) == k:
            if remaining == 0:
                result.append(path[:])
            return
        for digit in range(start, 10):
            if digit > remaining:
                break
            path.append(digit)
            backtrack(digit + 1, remaining - digit)
            path.pop()

    backtrack(1, n)
    result.sort()
    return result

